/**
 * Static page content pulled from the production WordPress site.
 *
 * The pages themselves are Elementor layouts, so they are shipped as
 * snapshots: `src/content/manifest.json` holds the metadata + asset list of
 * every published page, `src/content/pages/<slug>.html` holds the markup.
 *
 * Both files are regenerated by `npm run sync:content`; never edit them by
 * hand.
 *
 * The catch-all route `src/app/[slug]/page.tsx` renders them.
 */

import { readFile } from 'node:fs/promises';
import path from 'node:path';

import manifest from '@/content/manifest.json';

export interface PageCategory {
  id: number;
  slug: string;
  name: string;
  count: number;
}

export interface PageAssetEntry {
  kind: 'style' | 'script' | 'inline';
  src?: string;
  code?: string;
  type?: string;
}

export interface PageAsset {
  slug: string;
  id: number;
  title: string;
  description: string;
  elementorId: number;
  bodyClass: string;
  stylesheets: string[];
  scripts: string[];
  inlineScripts: string[];
  assets: PageAssetEntry[];
  jsonLd: string | null;
  canonical: string;
  categories: PageCategory[];
}

export const pages = manifest as PageAsset[];

/**
 * Slugs that already have a hand-built route in this app. The catch-all
 * route must not shadow them.
 *
 * Phase 2F: these pages are rebuilt as native React routes on top of the
 * content extracted from production (`src/content/structured/`), using the
 * reusable UI kit in `src/components/ui/`.
 *
 * `about` is a native route as well: it is rebuilt on the architecture of
 * the Agntix template (`about-us`), with the wording of the production page
 * and the photos of the WordPress media library. Serving it from the
 * mirrored production markup would load the theme stylesheets of WordPress
 * into the whole page, and those stylesheets reach the header and the footer
 * of this app - the navigation loses its colour and the buttons lose their
 * shape.
 */
export const NATIVE_SLUGS = new Set([
  'about',
  'contact',
  'services',
  'locations',
  'home',
  'faq',
  'pricing',
  'team',
  'our-services',
  'blog-standard',
  'news-insight',
  'reservasi',
  'terms-conditions',
  'cookie-policy',
  'privacy-policy',
  'premium-coating-lp',
]);

export const pagesBySlug = new Map(pages.map((page) => [page.slug, page]));

/** Slugs served by the catch-all route. */
export const staticPageSlugs = pages
  .filter((page) => !NATIVE_SLUGS.has(page.slug))
  .map((page) => page.slug);

/** Read the Elementor markup of a page snapshot. */
export async function readPageHtml(slug: string): Promise<string> {
  const file = path.join(process.cwd(), 'src', 'content', 'pages', `${slug}.html`);
  return readFile(file, 'utf8');
}

export function getPage(slug: string): PageAsset | undefined {
  return pagesBySlug.get(slug);
}
